import { Project } from '../../src'
import { UnresolvedShape, VariableStatementShape } from '@servicenow/sdk-build-core'

describe('Now.UNRESOLVED plugin', () => {
    test('Parsing Now.UNRESOLVED in Fluent code', async () => {
        const project = new Project()
        const file = project.addFile({
            path: 'test.now.ts',
            content: 'export const test = Now.UNRESOLVED',
        })

        const variableStatement = (await file.getShapes()).find((s) => s.is(VariableStatementShape))
        expect(variableStatement).toBeDefined()

        const unresolvedShape = variableStatement.getInitializer()
        expect(unresolvedShape.is(UnresolvedShape)).toBe(true)
        expect(unresolvedShape.getCode()).toBe(UnresolvedShape.CODE)
        expect(unresolvedShape.getValue()).toBe(UnresolvedShape.VALUE)
    })

    test('Committing Now.UNRESOLVED to Fluent code', async () => {
        const project = new Project()
        const file = project.addFile({ path: 'test.now.ts', content: '' })

        const { changedFiles } = await project.transform(
            new VariableStatementShape({
                source: file.addStatement(),
                isExported: true,
                variableName: 'test',
                initializer: new UnresolvedShape({ source: file.unwrap() }),
            })
        )

        expect(changedFiles).toHaveLength(1)
        expect(file).toStrictEqual(changedFiles[0])
        expect(file.getContent()).toBe('export const test = Now.UNRESOLVED\n')
    })
})
